using System;using System.Data;using System.Drawing;using System.Windows.Forms;
namespace AshkanHotelManager{public partial class HousekeepingBoardForm:Form{DataGridView grid;ComboBox room,status,priority;TextBox task,assigned;public HousekeepingBoardForm(){InitializeComponent();Text=App.T("housekeepingBoard");BackColor=Ui.Bg;Build();LoadData();App.ApplyDirection(this);}void Build(){var head=new Label{Text=App.T("housekeepingBoard"),Dock=DockStyle.Top,Height=64,Font=Ui.Font(22,FontStyle.Bold),ForeColor=Ui.Text,Padding=new Padding(18)};Controls.Add(head);var top=Ui.SurfacePanel();top.Dock=DockStyle.Top;top.Height=110;room=new ComboBox{Width=110,DropDownStyle=ComboBoxStyle.DropDownList};foreach(DataRow r in DataStore.Db.Tables["Rooms"].Rows)room.Items.Add(Convert.ToString(r["Number"]));status=new ComboBox{Width=120,DropDownStyle=ComboBoxStyle.DropDownList};status.Items.AddRange(new object[]{"Open","In Progress","Completed"});status.SelectedIndex=0;priority=new ComboBox{Width=100,DropDownStyle=ComboBoxStyle.DropDownList};priority.Items.AddRange(new object[]{"Low","Normal","High","Urgent"});priority.SelectedIndex=1;task=new TextBox{Width=240};assigned=new TextBox{Width=150};var add=Ui.Btn(App.T("addTask"));add.Width=120;add.Click+=(s,e)=>Add();var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),FlowDirection=App.Persian?FlowDirection.RightToLeft:FlowDirection.LeftToRight};flow.Controls.AddRange(new Control[]{room,task,assigned,priority,status,add});top.Controls.Add(flow);Controls.Add(top);grid=new DataGridView{Dock=DockStyle.Fill};Ui.Grid(grid);grid.CellDoubleClick+=(s,e)=>Complete(e.RowIndex);Controls.Add(grid);grid.BringToFront();top.BringToFront();head.BringToFront();}void Add(){if(room.SelectedItem==null||String.IsNullOrWhiteSpace(task.Text))return;DataStore.Db.Tables["Housekeeping"].Rows.Add(DataStore.Next("Housekeeping"),room.Text,task.Text,assigned.Text,priority.Text,status.Text,DateTime.Now.ToString("yyyy-MM-dd HH:mm"));DataStore.Save();LoadData();}void Complete(int i){if(i<0)return;var v=grid.Rows[i].DataBoundItem as DataRowView;if(v==null)return;v.Row["Status"]="Completed";string rn=Convert.ToString(v.Row["Room"]);var rr=DataStore.Db.Tables["Rooms"].Select("Number='"+rn.Replace("'","''")+"'");if(rr.Length>0&&Convert.ToString(rr[0]["Status"])=="Cleaning")rr[0]["Status"]="Available";DataStore.Save();LoadData();}void LoadData(){grid.DataSource=new DataView(DataStore.Db.Tables["Housekeeping"]);}}}